cases.source:
let
  plainValue = 10;
  simpleFn = arg: arg + 1;
  destructuredFn = { lib, stdenv }: lib.getName stdenv;
  curriedFn = a: b: builtins.toString (a + b);
in
{
  exportedValue = plainValue;
  exportedFn = curriedFn;
}

let
  inherit lib;
  inherit (pkgs) stdenv writeShellScriptBin;
in
stdenv.mkDerivation {}

let
  local = import ./x.nix;
  defaultFile = builtins.import ./dir;
  packageSet = import <nixpkgs> {};
  fromSources = import sources.nixpkgs {};
  dynamic = import selectedPath;
in
local

{ config, lib, ... }:
{
  imports = [ ./hardware.nix ../common inputs.foo.nixosModules.bar ];
  home-manager.users.demo.imports = [ ./home.nix ];
  flake.modules = [ ./configuration.nix ];
  notAModuleList = [ ./ignored.nix ];
}

{ pkgs, newScope }:
let
  hello = pkgs.callPackage ./pkgs/hello { };
  tools = pkgs.callPackages ../tools/all.nix { };
  dynamic = pkgs.callPackage pkgPath { };
in
{
  inherit hello tools dynamic;
}

{ lib, stdenv }:
let
  localValue = 10;
in
{
  exported = localValue;
  package = { name }: stdenv.mkDerivation { inherit name; };
  nested = {
    privateNested = true;
  };
  inherit (lib) licenses;
}

-module(m).

-record(state, {
    store = #{} :: map(),
    counter = 0 :: non_neg_integer()
}).

resource "aws_s3_bucket" "my_bucket" {
  bucket = "example"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

output "bucket_arn" {
  value = aws_s3_bucket.my_bucket.arn
}

module "vpc" {
  source = "./modules/vpc"
  cidr   = var.vpc_cidr
}

provider "aws" {
  region = "us-east-1"
}

locals {
  prefix      = "prod"
  full_name   = "${local.prefix}-app"
  max_retries = 3
}

terraform {
  required_version = ">= 1.5"
}

variable "region" {}
resource "aws_s3_bucket" "b" {
  bucket = var.region
}

output "vpc_id" {
  value = module.vpc.vpc_id
}

output "m" {
  value = module.vpc
}

module "s3" {
  source  = "terraform-aws-modules/s3-bucket/aws"
  version = "4.0.0"
  bucket  = "x"
}
module "net" {
  source = "git::https://example.com/net.git"
  cidr   = "10.0.0.0/16"
}

resource "aws_eks_cluster" "this" {
  vpc_id = module.vpc.outputs.vpc_id
}

output "x" {
  value = module.vpc.vpc_id
}

resource "aws_instance" "new" {}
moved {
  from = aws_instance.old
  to   = aws_instance.new
}
import {
  to = aws_s3_bucket.b
  id = "bucket-name"
}
removed {
  from = module.legacy.aws_iam_role.r
}

check "health" {
  data "http" "ping" {
    url = var.endpoint
  }
  assert {
    condition     = data.http.ping.status_code == 200 && var.strict
    error_message = "unhealthy"
  }
}

provider "aws" {
  region = "us-east-1"
}
provider "aws" {
  alias  = "east"
  region = "us-east-2"
}
resource "aws_s3_bucket" "b" {
  provider = aws.east
  bucket   = "x"
}
resource "google_service_account" "sa" {
  provider = google-beta
}

module "vpc" {
  source    = "./modules/vpc"
  providers = {
    aws = aws.east
  }
}

output "account" {
  value = data.aws_caller_identity.current.account_id
}

resource "aws_iam_policy" "p" {
  policy = aws_s3_bucket.my.arn
}

locals {
  prefix = "prod"
  name   = "${local.prefix}-app"
}
